package nl.giejay.android.tv.immich.map

/**
 * The world as a grid of land cells for the map page, drawn as a dot matrix. The data (res/raw/world_land_dots.bin)
 * is generated by tools/map/make_world_dots.py from the public domain Natural Earth land polygons; keep the
 * constants in sync with that script.
 */
object WorldDots {
    const val COLS = 240
    const val ROWS = 94
    const val LAT_TOP = 84.0
    const val LAT_BOTTOM = -57.0

    /** Width divided by height of the map area. */
    const val ASPECT = (360.0 / (LAT_TOP - LAT_BOTTOM)).toFloat()

    /** One bit per cell, row by row from the north-west, most significant bit first; true is land. */
    fun decode(bytes: ByteArray, cols: Int = COLS, rows: Int = ROWS): BooleanArray =
        BooleanArray(cols * rows) { index ->
            val byte = bytes.getOrNull(index / 8)?.toInt() ?: 0
            (byte shr (7 - index % 8)) and 1 == 1
        }

    /** 0 at 180 degrees west, 1 at 180 degrees east. */
    fun x(lon: Double): Float = ((lon + 180.0) / 360.0).coerceIn(0.0, 1.0).toFloat()

    /** 0 at the top of the map, 1 at the bottom; positions beyond the drawn latitudes sit at the edge. */
    fun y(lat: Double): Float = ((LAT_TOP - lat) / (LAT_TOP - LAT_BOTTOM)).coerceIn(0.0, 1.0).toFloat()
}
